import{_ as t,c as i,o as a,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"ESTABLISHING THE UNITED STATES INVESTMENT ACCELERATOR","description":"","frontmatter":{"title":"ESTABLISHING THE UNITED STATES INVESTMENT ACCELERATOR","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/establishing-the-united-states-investment-accelerator/","publishDate":"2025-03-31T18:04:53-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-31-establishing-the-united-states-investment-accelerator.md","filePath":"executive-orders/2025-03-31-establishing-the-united-states-investment-accelerator.md"}'),s={name:"executive-orders/2025-03-31-establishing-the-united-states-investment-accelerator.md"};function r(o,e,l,c,h,d){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="establishing-the-united-states-investment-accelerator" tabindex="-1">ESTABLISHING THE UNITED STATES INVESTMENT ACCELERATOR <a class="header-anchor" href="#establishing-the-united-states-investment-accelerator" aria-label="Permalink to &quot;ESTABLISHING THE UNITED STATES INVESTMENT ACCELERATOR&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/establishing-the-united-states-investment-accelerator/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/establishing-the-united-states-investment-accelerator/</a></p><p>Published: 2025-03-31T18:04:53-04:00</p><ul><li><p>The executive order addresses the need to streamline and modernize U.S. regulatory processes to attract domestic and foreign investments.</p></li><li><p>Acknowledges that existing regulations complicate and hinder investment, permitting, and construction due to overlapping Federal, State, and local legal frameworks.</p></li><li><p>It establishes the goal of enhancing Federal assistance for companies looking to invest and build in the U.S. to promote economic prosperity.</p></li><li><p><strong>Creation of the United States Investment Accelerator:</strong></p><ul><li>The Secretary of Commerce, in coordination with the Secretary of the Treasury and the Assistant to the President for Economic Policy, will establish the Investment Accelerator within 30 days.</li><li>This office aims to facilitate investments over $1 billion by: <ul><li>Helping investors navigate government regulatory processes efficiently.</li><li>Reducing regulatory burdens.</li><li>Increasing access to national resources when consistent with the law.</li><li>Facilitating research collaborations with national labs and working with State governments to reduce investment barriers.</li></ul></li></ul></li><li><p>The Investment Accelerator will have:</p><ul><li>An Executive Director and a team of legal, transactional, operational, and support staff.</li><li>Oversight of the CHIPS Program Office, responsible for ensuring better deals for taxpayers.</li></ul></li><li><p>Identification of mechanisms in Federal law to assist investors while ensuring national security protections.</p></li><li><p>Clarifies that the order does not impair the authority of executive agencies or the Office of Management and Budget.</p></li><li><p>Implementation is subject to applicable law and available appropriations, with no creation of enforceable rights or benefits against the U.S. or its entities.</p></li></ul>',4)]))}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
